using System;

namespace Tsumo.Tests
{
    public static class Node_modules_Tsumo_engine_src_markdown_toc
    {
        internal static string indent(int depth)
        {
            string @out = "";
            for (double i = 0; i < depth; i++)
            {
                @out += "  ";
            }
            return @out;
        }
        internal static void appendInlinePlainText(Markdig.Syntax.Inlines.Inline inline, TextBuilder output)
        {
            if ((object?)inline is Markdig.Syntax.Inlines.LiteralInline)
            {
                Markdig.Syntax.Inlines.LiteralInline literal = (Markdig.Syntax.Inlines.LiteralInline)inline;
                output.append(literal.ToString());
                return;
            }
            if ((object?)inline is Markdig.Syntax.Inlines.CodeInline)
            {
                Markdig.Syntax.Inlines.CodeInline code = (Markdig.Syntax.Inlines.CodeInline)inline;
                output.append(code.Content);
                return;
            }
            if ((object?)inline is Markdig.Syntax.Inlines.HtmlEntityInline)
            {
                Markdig.Syntax.Inlines.HtmlEntityInline entity = (Markdig.Syntax.Inlines.HtmlEntityInline)inline;
                output.append(entity.Transcoded.ToString());
                return;
            }
            if ((object?)inline is Markdig.Syntax.Inlines.AutolinkInline)
            {
                Markdig.Syntax.Inlines.AutolinkInline autolink = (Markdig.Syntax.Inlines.AutolinkInline)inline;
                output.append(autolink.Url);
                return;
            }
            if ((object?)inline is Markdig.Syntax.Inlines.LineBreakInline)
            {
                output.append(" ");
                return;
            }
            if ((object?)inline is Markdig.Syntax.Inlines.ContainerInline)
            {
                Markdig.Syntax.Inlines.ContainerInline container = (Markdig.Syntax.Inlines.ContainerInline)inline;
                Markdig.Syntax.Inlines.ContainerInline.Enumerator it = container.GetEnumerator();
                while (it.MoveNext())
                {
                    appendInlinePlainText(it.Current, output);
                }
                it.Dispose();
            }
        }
        internal static string getHeadingPlainText(Markdig.Syntax.HeadingBlock heading)
        {
            Markdig.Syntax.Inlines.ContainerInline? inline = heading.Inline;
            if (inline is null)
            {
                return "";
            }
            TextBuilder output = new TextBuilder();
            appendInlinePlainText(inline, output);
            return output.toString();
        }
        internal static Tsonic.CSharp.Js.JSArray<TocHeading> collectHeadingsFromAst(Markdig.Syntax.ContainerBlock document)
        {
            Tsonic.CSharp.Js.JSArray<TocHeading> headings = Tsonic.CSharp.Js.JSArray<TocHeading>.of([]);
            collectHeadingsRecursive(document, headings);
            return headings;
        }
        internal static void collectHeadingsRecursive(Markdig.Syntax.ContainerBlock container, Tsonic.CSharp.Js.JSArray<TocHeading> headings)
        {
            Markdig.Syntax.ContainerBlock.Enumerator it = container.GetEnumerator();
            while (it.MoveNext())
            {
                Markdig.Syntax.Block block = it.Current;
                if ((object?)block is Markdig.Syntax.HeadingBlock)
                {
                    Markdig.Syntax.HeadingBlock heading = (Markdig.Syntax.HeadingBlock)block;
                    Markdig.Renderers.Html.HtmlAttributes? attrs = Markdig.Renderers.Html.HtmlAttributesExtensions.TryGetAttributes(heading);
                    string id = attrs?.Id ?? "";
                    string text = getHeadingPlainText(heading);
                    headings.push(new TocHeading(heading.Level, text, id));
                }
                if ((object?)block is Markdig.Syntax.ContainerBlock)
                {
                    collectHeadingsRecursive((Markdig.Syntax.ContainerBlock)block, headings);
                }
            }
            it.Dispose();
        }
        public static Func<string, string> escapeHtmlText
        {
            get;
            private set;
        } = default(Func<string, string>)!;
        public static Func<string, string> generateTableOfContents
        {
            get;
            private set;
        } = default(Func<string, string>)!;
        private static readonly System.Lazy<object?> __tsonic_module_initialization = new System.Lazy<object?>(() => __tsonic_module_init_core());
        private static object? __tsonic_module_init_core()
        {
            Node_modules_Tsumo_engine_src_markdown_pipeline.__tsonic_module_init();
            escapeHtmlText = (string text) =>
            {
                string result = text;
                result = Tsonic.CSharp.Js.String.replaceAll(result, "&", "&amp;");
                result = Tsonic.CSharp.Js.String.replaceAll(result, "<", "&lt;");
                result = Tsonic.CSharp.Js.String.replaceAll(result, ">", "&gt;");
                result = Tsonic.CSharp.Js.String.replaceAll(result, "\"", "&quot;");
                return result;
            };
            generateTableOfContents = (string markdown) =>
            {
                Markdig.Syntax.MarkdownDocument document = Markdig.Markdown.Parse(markdown, Node_modules_Tsumo_engine_src_markdown_pipeline.markdownPipeline);
                Tsonic.CSharp.Js.JSArray<TocHeading> headings = collectHeadingsFromAst(document);
                if (headings.length == 0)
                {
                    return "<nav id=\"TableOfContents\"></nav>";
                }
                TextBuilder output = new TextBuilder();
                output.append("<nav id=\"TableOfContents\">\n");
                Tsonic.CSharp.Js.JSArray<TocListFrame> listStack = Tsonic.CSharp.Js.JSArray<TocListFrame>.of([]);
                int currentLevel = 0;
                for (double i = 0; i < headings.length; i++)
                {
                    TocHeading h = headings[i];
                    int targetLevel = h.level;
                    if (currentLevel != 0 && targetLevel > currentLevel + 1)
                    {
                        targetLevel = currentLevel + 1;
                    }
                    if (listStack.length == 0)
                    {
                        output.append($"{indent(1)}<ul>\n");
                        listStack.push(new TocListFrame(targetLevel));
                        currentLevel = targetLevel;
                    }
                    while (listStack.length > 0 && targetLevel < currentLevel)
                    {
                        TocListFrame top = listStack[listStack.length - 1];
                        if (top.liOpen)
                        {
                            output.append($"{indent(listStack.length + 1)}</li>\n");
                            top.liOpen = false;
                        }
                        output.append($"{indent(listStack.length)}</ul>\n");
                        Tsonic.CSharp.Js.Array.popReference(listStack);
                        currentLevel = listStack.length > 0 ? listStack[listStack.length - 1].level : 0;
                    }
                    if (listStack.length == 0)
                    {
                        output.append($"{indent(1)}<ul>\n");
                        listStack.push(new TocListFrame(targetLevel));
                        currentLevel = targetLevel;
                    }
                    if (targetLevel == currentLevel)
                    {
                        TocListFrame top_1 = listStack[listStack.length - 1];
                        if (top_1.liOpen)
                        {
                            output.append($"{indent(listStack.length + 1)}</li>\n");
                            top_1.liOpen = false;
                        }
                    }
                    if (targetLevel > currentLevel)
                    {
                        output.append($"{indent(listStack.length + 1)}<ul>\n");
                        listStack.push(new TocListFrame(targetLevel));
                        currentLevel = targetLevel;
                    }
                    output.append($"{indent(listStack.length + 1)}<li><a href=\"#{h.id}\">{escapeHtmlText(h.text)}</a>\n");
                    listStack[listStack.length - 1].liOpen = true;
                }
                while (listStack.length > 0)
                {
                    TocListFrame top_2 = listStack[listStack.length - 1];
                    if (top_2.liOpen)
                    {
                        output.append($"{indent(listStack.length + 1)}</li>\n");
                        top_2.liOpen = false;
                    }
                    output.append($"{indent(listStack.length)}</ul>\n");
                    Tsonic.CSharp.Js.Array.popReference(listStack);
                }
                output.append("</nav>");
                return output.toString();
            };
            return null;
        }
        public static void __tsonic_module_init()
        {
            _ = __tsonic_module_initialization.Value;
        }
    }
    public class TocHeading
    {
        public int level;
        public string text;
        public string id;
        public TocHeading(int level, string text, string id)
        {
            this.level = level;
            this.text = text;
            this.id = id;
        }
    }
    public class TocListFrame
    {
        public int level;
        public bool liOpen;
        public TocListFrame(int level)
        {
            this.level = level;
            this.liOpen = false;
        }
    }
